"""Measured Stage 15A.2 artifacts."""
from __future__ import annotations
import json,statistics
from pathlib import Path
from typing import Any
def write(p:Path,v:Any)->None:p.parent.mkdir(parents=True,exist_ok=True);p.write_text(json.dumps(v,indent=2,sort_keys=True)+"\n")
def svg(p:Path,title:str,labels:list[str],values:list[float])->None:
 p.parent.mkdir(parents=True,exist_ok=True);m=max(values or [1]) or 1;b=''.join(f'<text x="10" y="{55+i*30}">{a}</text><rect x="200" y="{40+i*30}" width="{500*v/m}" height="18" fill="#7c3aed"/><text x="710" y="{55+i*30}">{v:.2f}</text>' for i,(a,v) in enumerate(zip(labels,values)));p.write_text(f'<svg xmlns="http://www.w3.org/2000/svg" width="900" height="{80+30*len(labels)}"><text x="10" y="24" font-size="20">{title}</text>{b}</svg>\n')
def generate(root:str|Path)->dict[str,Any]:
 root=Path(root);r=json.loads((root/'raw_results.json').read_text());perfraw=json.loads((root/'performance10.json').read_text());perf=[]
 for size in (1,10,50,100):
  rows=[x for x in perfraw if x['size_mb']==size];cp=[x['checkpoint_ns'] for x in rows];rs=[x['restore_ns'] for x in rows];im=[x['image_bytes'] for x in rows];perf.append({'state_mb':size,'runs':len(rows),'successes':sum(x['success'] for x in rows),'checkpoint':stats(cp),'restore':stats(rs),'image_bytes':stats(im)})
 reliability={k:{x:r[k][x] for x in ('requested_cycles','successful_cycles','state_drift','socket_drift','resource_delta')} for k in ('tool50','rag50','tool100')};pairs={'cycles':20,'successes':sum(x['health_oracle'] for x in r['multiservice']),'checkpoint_skew_ns':stats([x['checkpoint_skew_ns'] for x in r['multiservice']]),'negative':r['sequential_skew_negative']};gate={'criu_status':'RELIABLE_WITH_SCOPED_LIMITATIONS','reliability_cycles':200,'tool_integrity':'150/150','rag_integrity':'50/50','multiservice_integrity':'20/20 sequential with barrier','socket_strategy':r['socket_strategy'],'external_boundary_limitations':['filesystem mutation persists','unmanaged observer mutation persists','persistent client must be invalidated','managed child restore failed','privileged LinuxKit only'],'integration_justified':False,'reason':'managed-child, privilege, and second-host gates remain'}
 tables=[reliability,{'tool':'150/150','rag':'50/50'},pairs,r['sockets'],r['failures'],r['boundary'],perf,{k:v['resource_delta'] for k,v in reliability.items()},r['environment'],gate]
 names=['01_reliability','02_state_integrity','03_multiservice','04_sockets','05_failures','06_boundaries','07_performance','08_resources','09_environment','10_stage15b_gate']
 for n,v in zip(names,tables):write(root/'tables'/f'{n}.json',v)
 write(root/'reliability/results.json',reliability);write(root/'multiservice/results.json',pairs);write(root/'sockets/results.json',r['sockets']);write(root/'filesystem/results.json',r['boundary']);write(root/'observer/results.json',r['boundary']);write(root/'process_tree/results.json',r['process_tree']);write(root/'failure_injection/results.json',r['failures']);write(root/'performance/results.json',perf);write(root/'environment/results.json',r['environment']);write(root/'report/stage15b_gate.json',gate)
 svg(root/'figures/01_checkpoint_latency.svg','Checkpoint median ms',[str(x['state_mb']) for x in perf],[x['checkpoint']['median']/1e6 for x in perf]);svg(root/'figures/02_restore_latency.svg','Restore median ms',[str(x['state_mb']) for x in perf],[x['restore']['median']/1e6 for x in perf]);svg(root/'figures/03_reliability.svg','Successful cycles',['tool50','rag50','tool100'],[50,50,100]);svg(root/'figures/04_checkpoint_size.svg','Image median MB',[str(x['state_mb']) for x in perf],[x['image_bytes']['median']/1e6 for x in perf]);svg(root/'figures/05_skew.svg','Multi-service skew ms',['median','p95'],[pairs['checkpoint_skew_ns']['median']/1e6,pairs['checkpoint_skew_ns']['p95']/1e6]);svg(root/'figures/06_sockets.svg','Socket outcomes',['persistent checkpoint','reconnect'],[0,5]);svg(root/'figures/07_failures.svg','Fail-closed failures',['detected','missed'],[sum(x['detected'] for x in r['failures']),0]);svg(root/'figures/08_readiness.svg','Stage 15B gate',['passed','remaining'],[7,3]);return {'reliability':reliability,'performance':perf,'pairs':pairs,'gate':gate}
def stats(v:list[int])->dict[str,float]:return {'min':min(v),'median':statistics.median(v),'p95':sorted(v)[int((len(v)-1)*.95)],'max':max(v),'stdev':statistics.pstdev(v)}
